  function richText(value) {
    return esc(value).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>').replace(/\`(.+?)\`/g, '<code>$1</code>')
      .split('\n').map(line=>line.replace(/\s*\|\s*$/,'').trim()).filter(line=>line&&line!=='|').map(line => /^[-✔•]\s*/.test(line) ? `<li>${line.replace(/^[-✔•]\s*/,'')}</li>` : `<p>${line}</p>`).join('')
      .replace(/(<li>[\s\S]*?<\/li>)(?=<p>|$)/g, '$1');
  }
  function sheetTable(lines) {
    const rows={};
    lines.forEach(line=>{
      const cells=line.split('|').slice(1,-1).map(cell=>cell.trim());
      if(cells.length<2 || /^[- ]+$/.test(cells[0])) return;
      const cell=/^([A-Z]+)(\d+)$/.exec(cells[0]);
      if(!cell) return;
      const row=cell[2], column=cell[1];
      (rows[row]||(rows[row]={}))[column]=cells.slice(1).join(' | ').replace(/\s*\|\s*$/,'').trim();
    });
    const ordered=Object.entries(rows).sort((a,b)=>Number(a[0])-Number(b[0]));
    return `<div class="course-sheet">${ordered.map(([number,columns])=>{
      const label=(columns.A||'').trim(), content=Object.entries(columns).filter(([column])=>column!=='A').map(([,value])=>value).filter(Boolean).join('\n');
      if(!label && !content) return '';
      if(/^(категория|наименование|вид работ)$/i.test(label)||/^(информация|значение)$/i.test(content)) return '';
      if(label && !content && label===label.toUpperCase() && label.length>4) return `<h3 class="course-sheet-title">${esc(label)}</h3>`;
      const normalized=value=>String(value||'').toLocaleLowerCase('ru').replace(/[^а-яёa-z0-9]+/g,'');
      if(!content || normalized(content).length<3 || normalized(content)===normalized(label)) return '';
      const title=label || `Рабочий блок ${number}`;
      return `<details class="course-topic" ${Number(number)<5?'open':''}><summary><span>${esc(title)}</span><b>Открыть</b></summary><div class="course-topic-body">${richText(content||label)}</div></details>`;
    }).join('')}</div>`;
  }
  function markdown(raw) {
    const text=String(raw||'').replace(/^---[\s\S]*?---\s*/, '').replace(/## Первичный источник\s*[\s\S]*?(?=## Полное содержимое из источника)/, '').replace(/^> Полный структурированный экспорт[^\n]*\n?/gm, '').replace(/^\[Открыть[^\n]*\]\([^\n]*\)\s*$/gm, '').replace(/\r/g,'').replace(/<br\s*\/?>/gi,'\n');
    const lines=text.split('\n'), output=[];
    for(let index=0;index<lines.length;){
      if(/^\|/.test(lines[index])){const table=[];while(index<lines.length&&/^\|/.test(lines[index]))table.push(lines[index++]);output.push(sheetTable(table));continue;}
      const line=lines[index++].trim(); if(!line||line==='## Полное содержимое из источника'||/^(направляю|направляем)\s+актуальн\w*\s+форм\w*/i.test(line)) continue;
      if(/^#{1,3}\s/.test(line)){const heading=line.replace(/^#{1,3}\s/,'');output.push(`<h2 class="course-section-heading">${esc(heading.replace(/^Лист:\s*/,''))}</h2>`);continue;}
      output.push(`<div class="course-prose">${richText(line)}</div>`);
    }
    return output.join('');
  }
